{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "learn-skills",
  "description": "Personal skill collection for Claude Code, Codex, and other agents.",
  "owner": {
    "name": "xpzouying",
    "url": "https://github.com/xpzouying"
  },
  "plugins": [
    {
      "name": "learn-skills",
      "description": "Installs the full learn-skills toolkit. Registers every skill under the learn-skills namespace. Not for users who only want one skill — install a single skill entry instead.",
      "version": "0.1.0",
      "category": "development",
      "source": "./",
      "homepage": "https://github.com/xpzouying/learn-skills"
    },
    {
      "name": "webread",
      "description": "Save any http(s) URL as clean Markdown via the user's real Chrome (kimi-webbridge). Embedded images are downloaded to a sibling folder so saved articles work offline. Routes Twitter and Feishu URLs to dedicated CLIs. Not for local files or PDFs.",
      "version": "0.5.0",
      "category": "development",
      "source": "./skills/webread",
      "homepage": "https://github.com/xpzouying/learn-skills",
      "skills": ["./"],
      "strict": false
    }
  ]
}
